import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/english/vocabulary/animal-protection/insects-birds-and-small-animals/","title":"CH3.4 昆虫、鸟类与小型动物 | 英语","lang":"zh-CN","frontmatter":{"title":"CH3.4 昆虫、鸟类与小型动物","createTime":"2026-11-20T10:00:00.000Z","permalink":"/english/vocabulary/animal-protection/insects-birds-and-small-animals/"},"readingTime":{"minutes":32.39,"words":9718},"git":{"createdTime":1795161551000},"filePathRelative":"english/vocabulary/animal-protection/4.insects-birds-and-small-animals.md","headers":[],"bulletin":false}`),a={name:`4.insects-birds-and-small-animals.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="insect" tabindex="-1"><a class="header-anchor" href="#insect"><span>Insect</span></a></h2><p class="vc-meta"><strong>/ˈɪnsekt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>昆虫（六足、三体节的无脊椎动物）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>insects and birds</td><td>昆虫与鸟类</td></tr><tr><td>a biting insect</td><td>咬人的昆虫</td></tr><tr><td>insect species</td><td>昆虫物种</td></tr><tr><td>insect population</td><td>昆虫数量</td></tr><tr><td>insect bite</td><td>虫咬</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the decline in insect numbers recorded at the three sites.</p><blockquote><p>该图显示了三个样点记录到的昆虫数量下降情况。</p></blockquote><p><strong>Writing Task 2</strong> Insects pollinate most of the crops we eat, yet their populations are falling faster than those of almost any other group.</p><blockquote><p>昆虫为我们食用的大部分作物授粉，然而它们的数量下降得比几乎任何其他类群都快。</p></blockquote><p><strong>Speaking</strong> Insects don&#39;t bother me at all, unless they&#39;re in my bedroom at two in the morning.</p><blockquote><p>昆虫完全不困扰我，除非凌晨两点出现在我卧室里。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>bug</td><td>虫子</td><td>口语，泛指一切小虫</td></tr><tr><td>pest</td><td>害虫</td><td>强调有害，非分类概念</td></tr><tr><td>arthropod</td><td>节肢动物</td><td>上位类群，含蛛形纲</td></tr><tr><td>creepy-crawly</td><td>小爬虫</td><td>儿语，带厌恶感</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> in-（在内）+ 拉丁 <em>secare</em>（切）→ &quot;身体分节的&quot;</li><li><strong>Family:</strong> insecticide 杀虫剂 / insectivore 食虫动物 / section 部分（同源&quot;切&quot;）</li><li><strong>Memory Tip:</strong> 词根 secare 是&quot;切&quot;——昆虫的身体被&quot;切成&quot;头、胸、腹三节，这是它区别于蜘蛛（两节）的关键。同族的 section 也是&quot;切出来的一部分&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>蜘蛛、蜈蚣不是 insect（它们不是六足三节），属 arthropod。</li><li>可数：insects；泛指一类时用复数。<s>an insect</s> 单数泛指不自然。</li><li>拼写 in-sect，重音在首音节 /ˈɪnsekt/。</li></ul></div><div class="vocab-card"><h2 id="worm" tabindex="-1"><a class="header-anchor" href="#worm"><span>Worm</span></a></h2><p class="vc-meta"><strong>/wɜːm/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>蠕虫，蚯蚓（细长无足）</li><li>（喻）可怜虫；蠕虫型恶意程序</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>an earthworm</td><td>蚯蚓</td></tr><tr><td>worms in the soil</td><td>土壤里的蠕虫</td></tr><tr><td>a can of worms</td><td>一堆麻烦（喻）</td></tr><tr><td>worm casts</td><td>蚯蚓粪</td></tr><tr><td>parasitic worms</td><td>寄生蠕虫</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how worms aerate the soil as they move through it.</p><blockquote><p>该示意图展示了蠕虫如何在土中穿行时给土壤通气。</p></blockquote><p><strong>Writing Task 2</strong> A handful of soil may contain more living things than a rainforest canopy, and most of them are worms, mites and microbes nobody ever notices.</p><blockquote><p>一把土里的生物可能比雨林树冠层还多，其中大多是无人注意的蠕虫、螨虫与微生物。</p></blockquote><p><strong>Speaking</strong> I dug the whole bed over and found exactly one worm, which was slightly depressing.</p><blockquote><p>我把整块地翻了一遍，只找到一条蚯蚓，有点令人沮丧。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>earthworm</td><td>蚯蚓</td><td>特指陆生蚯蚓</td></tr><tr><td>larva</td><td>幼虫</td><td>昆虫的幼体阶段，形态不同</td></tr><tr><td>maggot</td><td>蛆</td><td>蝇类幼虫，口语带厌恶</td></tr><tr><td>caterpillar</td><td>毛虫</td><td>蝶蛾幼虫，有足</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>wyrm</em>（蛇、虫），与拉丁 <em>vermis</em> 同源</li><li><strong>Family:</strong> worm 蠕虫 / wormy 有虫的 / vermin 害虫（同源）/ vermicelli 细面条（&quot;小虫形&quot;）</li><li><strong>Memory Tip:</strong> 词根 verm- 是&quot;虫&quot;：vermin 害兽、vermicelli 细面像小虫。英语用&quot;虫&quot;形容细长之物，这个联想让 worm 与 vermin 一次记住。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>蚯蚓是 <strong>earthworm</strong>，只说 worm 也可，但更泛。</li><li>&quot;a can of worms&quot; 意为&quot;一堆棘手问题&quot;，不是&quot;一罐虫&quot;。</li><li>拼写 worm，别与 <s>warm</s> 混。</li></ul></div><div class="vocab-card"><h2 id="pest" tabindex="-1"><a class="header-anchor" href="#pest"><span>Pest</span></a></h2><p class="vc-meta"><strong>/pest/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>害虫，有害动物（农业、居家语境）</li><li>讨厌的人（口语）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a pest problem</td><td>虫害问题</td></tr><tr><td>pest control</td><td>害虫防治</td></tr><tr><td>agricultural pests</td><td>农业害虫</td></tr><tr><td>pests and diseases</td><td>病虫害</td></tr><tr><td>a serious pest</td><td>一种严重的害虫</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows crop losses caused by pests in each region.</p><blockquote><p>该图显示了各地区由虫害造成的作物损失。</p></blockquote><p><strong>Writing Task 2</strong> Intensive farming removes the hedges and ponds that shelter the predators which once kept pests in check.</p><blockquote><p>集约化农业清除了树篱与池塘，而那里正栖息着曾控制害虫的捕食者。</p></blockquote><p><strong>Speaking</strong> Wasps are a pest, but they do eat aphids, so I&#39;ve stopped swatting them.</p><blockquote><p>黄蜂是害虫，但它们确实吃蚜虫，所以我不再拍它们了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>vermin</td><td>害兽</td><td>多指鼠类等，带强烈厌恶</td></tr><tr><td>insect</td><td>昆虫</td><td>中性分类词，无&quot;有害&quot;义</td></tr><tr><td>weed</td><td>杂草</td><td>只用于植物</td></tr><tr><td>nuisance</td><td>讨厌之物</td><td>抽象、通用，不含生物义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>pestis</em>（瘟疫、灾祸）</li><li><strong>Family:</strong> pesticide 杀虫剂 / pestilence 瘟疫 / pest 害虫</li><li><strong>Memory Tip:</strong> pest 与 pestilence（瘟疫）同源——害虫带来的正是&quot;灾&quot;。所以 pesticide 是&quot;杀 pest 的东西&quot;，而 herbicide 杀的是 herb（草），两个 -cide 别混。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>pest 是&quot;从人的利益看有害&quot;，不是分类学词：蜜蜂可以是 pest，也可以是 pollinator。</li><li>&quot;病虫害&quot;固定说 <strong>pests and diseases</strong>。</li><li>拼写 pest，别与 <s>past</s> 混。</li></ul></div><div class="vocab-card"><h2 id="parasite" tabindex="-1"><a class="header-anchor" href="#parasite"><span>Parasite</span></a></h2><p class="vc-meta"><strong>/ˈpærəsaɪt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>寄生生物，寄生虫</li><li>靠他人供养的人，寄生虫（贬义）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a parasite on ...</td><td>寄生于……的寄生虫</td></tr><tr><td>intestinal parasites</td><td>肠道寄生虫</td></tr><tr><td>parasitic infection</td><td>寄生虫感染</td></tr><tr><td>host and parasite</td><td>宿主与寄生者</td></tr><tr><td>a social parasite</td><td>社会寄生虫</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the life cycle of a parasite that passes from snails to birds.</p><blockquote><p>该示意图展示了一种从螺类传到鸟类的寄生虫的生活史。</p></blockquote><p><strong>Writing Task 2</strong> A parasite that kills its host too quickly destroys its own habitat, which is why the most successful ones do very little harm.</p><blockquote><p>迅速杀死宿主的寄生虫等于毁掉自己的栖息地，因此最成功的寄生者往往危害极小。</p></blockquote><p><strong>Speaking</strong> The cat brought home a flea-covered bird and gave the whole house parasites, basically.</p><blockquote><p>猫叼回一只长满跳蚤的鸟，基本等于给全屋发了寄生虫。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>bacterium</td><td>细菌</td><td>有些致病，但不&quot;寄居取食&quot;</td></tr><tr><td>virus</td><td>病毒</td><td>严格说也是寄生，但不称 parasite</td></tr><tr><td>scavenger</td><td>食腐动物</td><td>吃死物，不依附活体</td></tr><tr><td>freeloader</td><td>白吃白喝者</td><td>口语，只用于人</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> para-（在旁边）+ sitos（食物）→ &quot;在别人旁边蹭饭的&quot;</li><li><strong>Family:</strong> parasitic 寄生的 / parasitism 寄生关系 / para- 前缀（并行、辅助）</li><li><strong>Memory Tip:</strong> para（旁边）+ sitos（饭）＝&quot;在旁边吃饭的人&quot;。这个词源本身就是一个笑话，记住它比背释义更牢。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词是 <strong>parasitic</strong>：parasitic <strong>worms</strong> ✔ / <s>parasite worms</s> ✘</li><li>重音在首音节 /ˈpærəsaɪt/，结尾读 /-saɪt/ 不是 /-siːt/。</li><li>与 <strong>predator</strong> 区分：捕食者杀死猎物，寄生者依赖宿主活着。</li></ul></div><div class="vocab-card"><h2 id="spider" tabindex="-1"><a class="header-anchor" href="#spider"><span>Spider</span></a></h2><p class="vc-meta"><strong>/ˈspaɪdə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>蜘蛛（八足，身体两节）</li><li>蜘蛛网状的物；（网络）爬虫程序</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a spider&#39;s web</td><td>蜘蛛网</td></tr><tr><td>spiders and insects</td><td>蜘蛛与昆虫</td></tr><tr><td>spider silk</td><td>蛛丝</td></tr><tr><td>a venomous spider</td><td>有毒的蜘蛛</td></tr><tr><td>spider bite</td><td>蜘蛛咬伤</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram compares the structure of a spider&#39;s web at two stages.</p><blockquote><p>该示意图比较了蜘蛛网在两个阶段的结构。</p></blockquote><p><strong>Writing Task 2</strong> Spider silk is stronger than steel by weight, and researchers have spent decades trying to reproduce it artificially.</p><blockquote><p>蛛丝按重量计比钢还强，研究者花了几十年试图人工复制它。</p></blockquote><p><strong>Speaking</strong> There&#39;s a spider in the corner of my ceiling that I&#39;ve decided to consider a roommate.</p><blockquote><p>我天花板角落有只蜘蛛，我决定把它当室友。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>arachnid</td><td>蛛形纲动物</td><td>分类学词，含蝎、螨</td></tr><tr><td>insect</td><td>昆虫</td><td>六足三节，与蜘蛛不同</td></tr><tr><td>mite</td><td>螨</td><td>体积极小，同属蛛形纲</td></tr><tr><td>tarantula</td><td>捕鸟蛛</td><td>具体一种大型蜘蛛</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>spīþra</em>（纺线者）</li><li><strong>Family:</strong> spider 蜘蛛 / spiderweb 蛛网 / spidery 细长如蛛腿的 / spin 纺（关联）</li><li><strong>Memory Tip:</strong> 古英语原义是&quot;纺线者&quot;——蜘蛛就是&quot;会纺线的虫&quot;。同族 spin（纺）帮你把&quot;吐丝&quot;和&quot;纺线&quot;联系起来。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>蜘蛛不是昆虫：八条腿、两节身体，属蛛形纲。</li><li>&quot;蜘蛛网&quot;是 <strong>spider web</strong> 或 spider&#39;s web，口语也说 cobweb（旧网、灰尘网）。</li><li>拼写 spi-der，重音在首音节。</li></ul></div><div class="vocab-card"><h2 id="butterfly" tabindex="-1"><a class="header-anchor" href="#butterfly"><span>Butterfly</span></a></h2><p class="vc-meta"><strong>/ˈbʌtəflaɪ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>蝴蝶</li><li>蝶泳（butterfly stroke）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>butterflies and bees</td><td>蝴蝶与蜜蜂</td></tr><tr><td>a butterfly&#39;s wings</td><td>蝴蝶的翅膀</td></tr><tr><td>butterfly species</td><td>蝴蝶物种</td></tr><tr><td>butterfly stroke</td><td>蝶泳</td></tr><tr><td>butterflies in the stomach</td><td>心里发慌</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows how the butterfly&#39;s range has shifted north over thirty years.</p><blockquote><p>该地图显示了三十年间这种蝴蝶的分布范围如何向北移动。</p></blockquote><p><strong>Writing Task 2</strong> A butterfly that depends on a single plant species disappears the moment that plant is cleared, however common the butterfly once was.</p><blockquote><p>依赖单一植物的蝴蝶，在那种植物被清除的瞬间就会消失，无论它曾经多么常见。</p></blockquote><p><strong>Speaking</strong> We planted wildflowers to attract butterflies and ended up with an entire summer of them.</p><blockquote><p>我们种了野花想吸引蝴蝶，结果整个夏天都有蝴蝶。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>moth</td><td>蛾</td><td>夜行、触角羽状，与蝶并列</td></tr><tr><td>insect</td><td>昆虫</td><td>上位类群</td></tr><tr><td>caterpillar</td><td>毛虫</td><td>蝶的幼虫阶段</td></tr><tr><td>flutter</td><td>扑动</td><td>描述动作，不是物种</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> butter（黄油）+ fly（飞虫），传说因翅色如黄油或喜食黄油而得名</li><li><strong>Family:</strong> butterfly 蝴蝶 / butterfly effect 蝴蝶效应 / dragonfly 蜻蜓（同类构词）</li><li><strong>Memory Tip:</strong> 英语用&quot;X + fly&quot;造虫名：butterfly 蝴蝶、dragonfly 蜻蜓、firefly 萤火虫。记一个模板，一次收三个高频词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>蝴蝶（日行、触角棒状）与蛾（moth，夜行）要区分。</li><li>复数 <strong>butterflies</strong>：<s>butterflys</s> ✘</li><li>&quot;心里发慌&quot;是 have <strong>butterflies in one&#39;s stomach</strong>，固定搭配。</li></ul></div><div class="vocab-card"><h2 id="mosquito" tabindex="-1"><a class="header-anchor" href="#mosquito"><span>Mosquito</span></a></h2><p class="vc-meta"><strong>/məˈskiːtəʊ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>蚊子</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>mosquito bites</td><td>蚊子叮咬</td></tr><tr><td>a mosquito net</td><td>蚊帐</td></tr><tr><td>mosquito-borne disease</td><td>蚊媒疾病</td></tr><tr><td>mosquito larvae</td><td>蚊幼虫</td></tr><tr><td>mosquito repellent</td><td>驱蚊剂</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows reported cases of mosquito-borne disease in each province.</p><blockquote><p>该图显示了各省上报的蚊媒疾病病例数。</p></blockquote><p><strong>Writing Task 2</strong> Standing water is where mosquitoes breed, so clearing blocked drains does more for public health than any spraying campaign.</p><blockquote><p>积水是蚊子繁殖之处，因此疏通堵塞的下水道比任何喷药行动都更有利于公共健康。</p></blockquote><p><strong>Speaking</strong> The mosquitoes here are so big that people joke about them carrying off small dogs.</p><blockquote><p>这儿的蚊子大得人们开玩笑说能把小狗叼走。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>gnat</td><td>蠓，小飞虫</td><td>体型更小，口语泛称</td></tr><tr><td>midge</td><td>摇蚊</td><td>不吸血或微吸血，常见于水边</td></tr><tr><td>fly</td><td>蝇</td><td>双翅目统称，含蚊</td></tr><tr><td>insect</td><td>昆虫</td><td>上位类群</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 西班牙语 <em>mosquito</em>（小蝇），mosca（蝇）+ -ito（小）</li><li><strong>Family:</strong> mosquito 蚊子 / mosquito net 蚊帐 / mosquito coil 蚊香</li><li><strong>Memory Tip:</strong> 来自西班牙语&quot;小苍蝇&quot;，后缀 -ito 表&quot;小&quot;（如 burrito 小驴）。所以 mosquito 字面就是&quot;小飞虫&quot;，拼写的 -ito 是西语痕迹。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>复数 <strong>mosquitoes</strong>（也可 mosquitos，前者更常见）。</li><li>&quot;蚊帐&quot;是 mosquito net，不是 <s>mosquito curtain</s>。</li><li>重音在第二音节 /məˈskiːtəʊ/。</li></ul></div><div class="vocab-card"><h2 id="cricket" tabindex="-1"><a class="header-anchor" href="#cricket"><span>Cricket</span></a></h2><p class="vc-meta"><strong>/ˈkrɪkɪt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>蟋蟀，蛐蛐</li><li>板球（运动）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a cricket chirping</td><td>蟋蟀鸣叫</td></tr><tr><td>the sound of crickets</td><td>蟋蟀声</td></tr><tr><td>play cricket</td><td>打板球</td></tr><tr><td>a cricket match</td><td>板球比赛</td></tr><tr><td>not cricket</td><td>不公平（英式口语）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the chirping rate of crickets at different temperatures.</p><blockquote><p>该图比较了蟋蟀在不同温度下的鸣叫频率。</p></blockquote><p><strong>Writing Task 2</strong> In many cultures the cricket&#39;s song is a marker of autumn, and its disappearance from a city is noticed long before any survey records it.</p><blockquote><p>在许多文化里，蟋蟀的鸣声是秋天的标志；而它们从一座城市消失，往往在调查记录之前就已被察觉。</p></blockquote><p><strong>Speaking</strong> I couldn&#39;t sleep because of one cricket somewhere in the garden, and I never found it.</p><blockquote><p>我睡不着，就因为园子里有只蟋蟀，我还始终没找到它。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>grasshopper</td><td>蚱蜢</td><td>体型更大，白天活动</td></tr><tr><td>cicada</td><td>蝉</td><td>夏季鸣叫，声音更持续</td></tr><tr><td>katydid</td><td>螽斯</td><td>与蟋蟀近缘，鸣声不同</td></tr><tr><td>insect</td><td>昆虫</td><td>上位类群</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>criquer</em>（吱吱作响）→ 拟声词</li><li><strong>Family:</strong> cricket 蟋蟀；板球 / cricketer 板球运动员 / crick 脖子僵硬</li><li><strong>Memory Tip:</strong> 一个词两个世界：虫子与运动。英国人把板球也叫 cricket，据说是&quot;拄着小棍打球&quot;（cric 拐杖）。用&quot;小棍&quot;这个画面区分两义。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>同形异义，靠语境判断：play cricket 是板球，不是&quot;玩蟋蟀&quot;。</li><li>&quot;蟋蟀叫&quot;用 <strong>chirp</strong>，不用 <s>sing</s>（虽可拟人）。</li><li>拼写 cric-ket，双 c 不是 <s>crik-</s>。</li></ul></div><div class="vocab-card"><h2 id="frog" tabindex="-1"><a class="header-anchor" href="#frog"><span>Frog</span></a></h2><p class="vc-meta"><strong>/frɒɡ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>蛙，青蛙</li><li>（衣饰的）盘花纽扣；（铁路）辙叉</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a frog&#39;s habitat</td><td>蛙的栖息地</td></tr><tr><td>frogs and toads</td><td>蛙与蟾蜍</td></tr><tr><td>frog spawn</td><td>蛙卵</td></tr><tr><td>a frog pond</td><td>蛙池</td></tr><tr><td>frog species</td><td>蛙类物种</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the life cycle of a frog, from egg to adult.</p><blockquote><p>该示意图展示了蛙从卵到成体的生活史。</p></blockquote><p><strong>Writing Task 2</strong> Frogs are unusually sensitive to changes in water quality, which makes them useful indicators of how healthy a wetland really is.</p><blockquote><p>蛙对水质变化异常敏感，这使它们成为衡量湿地真实健康状况的有用指示物。</p></blockquote><p><strong>Speaking</strong> The frogs start up at about eleven every night, right under my window.</p><blockquote><p>每天夜里十一点左右青蛙就开始叫，就在我窗户底下。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>toad</td><td>蟾蜍</td><td>皮肤干燥有疙瘩，陆生为主</td></tr><tr><td>amphibian</td><td>两栖动物</td><td>上位类群，含蛙与蝾螈</td></tr><tr><td>tadpole</td><td>蝌蚪</td><td>蛙的幼体阶段</td></tr><tr><td>froglet</td><td>幼蛙</td><td>刚完成变态的小蛙</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>frogga</em></li><li><strong>Family:</strong> frog 蛙 / frogman 蛙人 / frogspawn 蛙卵 / leapfrog 跳背游戏</li><li><strong>Memory Tip:</strong> 蛙的一生是&quot;卵 → 蝌蚪 → 幼蛙 → 成蛙&quot;，英语对应 egg / tadpole / froglet / adult frog。按阶段背，比单记一个词有用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>蟾蜍是 <strong>toad</strong>，不是 frog 的一种俗称。</li><li>&quot;蛙卵&quot;是 <strong>frog spawn</strong>，不是 <s>frog eggs</s>（虽可理解）。</li><li>拼写 frog，别与 <s>frok</s> 混。</li></ul></div><div class="vocab-card"><h2 id="mouse" tabindex="-1"><a class="header-anchor" href="#mouse"><span>Mouse</span></a></h2><p class="vc-meta"><strong>/maʊs/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>老鼠，小鼠（比 rat 小）</li><li>鼠标</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a field mouse</td><td>田鼠</td></tr><tr><td>mice and rats</td><td>小鼠与大鼠</td></tr><tr><td>a mouse&#39;s nest</td><td>鼠窝</td></tr><tr><td>as quiet as a mouse</td><td>非常安静</td></tr><tr><td>a mouse click</td><td>点击鼠标</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows how mouse numbers changed after the owls were reintroduced.</p><blockquote><p>该图显示了重新引入猫头鹰后鼠类数量的变化。</p></blockquote><p><strong>Writing Task 2</strong> A single pair of mice can produce thousands of descendants in a year, which is why they are used in almost every laboratory study of reproduction.</p><blockquote><p>一对小鼠一年能产生数以千计的后代，这就是它们几乎被用于所有繁殖实验室研究的原因。</p></blockquote><p><strong>Speaking</strong> A mouse got into the cupboard and ate a corner off every single packet — very thorough.</p><blockquote><p>一只老鼠钻进橱柜，每个包装都啃掉一个角，非常有条理。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>rat</td><td>大鼠</td><td>体型更大，尾长、性凶</td></tr><tr><td>rodent</td><td>啮齿动物</td><td>分类类群，含鼠、兔类等</td></tr><tr><td>shrew</td><td>鼩鼱</td><td>外形似鼠但不同目，食虫</td></tr><tr><td>vole</td><td>田鼠</td><td>尾短、圆钝，野外常见</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>mūs</em>，与拉丁 <em>mus</em> 同源</li><li><strong>Family:</strong> mice 复数 / mousy 灰褐色的；胆小的 / mousetrap 捕鼠器</li><li><strong>Memory Tip:</strong> 复数是不规则变化 <strong>mice</strong>（像 tooth→teeth）。计算机鼠标沿用同词，所以&quot;两只鼠标&quot;也说 two mice，属幽默但通用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>复数 <strong>mice</strong>，不是 <s>mouses</s>。</li><li>mouse（小鼠）与 rat（大鼠）在科研语境严格区分。</li><li>&quot;安静得像老鼠&quot;是 as quiet as a mouse，固定比喻。</li></ul></div><div class="vocab-card"><h2 id="rat" tabindex="-1"><a class="header-anchor" href="#rat"><span>Rat</span></a></h2><p class="vc-meta"><strong>/ræt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>大鼠，耗子（体型大于 mouse）</li><li>叛徒，告密者（口语，贬义）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a rat infestation</td><td>鼠患</td></tr><tr><td>rats and mice</td><td>大鼠与小鼠</td></tr><tr><td>rat poison</td><td>鼠药</td></tr><tr><td>smell a rat</td><td>觉得可疑</td></tr><tr><td>a laboratory rat</td><td>实验大鼠</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows rat sightings reported in the city centre over five years.</p><blockquote><p>该图显示了五年来市中心上报的鼠类目击次数。</p></blockquote><p><strong>Writing Task 2</strong> Rats thrive wherever people leave food waste, so a clean street is a more effective policy than any poisoning programme.</p><blockquote><p>哪里有人留下食物垃圾，大鼠就在哪里繁荣，因此干净的街道比任何投毒计划都更有效。</p></blockquote><p><strong>Speaking</strong> I saw a rat the size of a cat on the platform, and everyone just pretended not to.</p><blockquote><p>我在站台上看见一只猫那么大的老鼠，大家都装作没看见。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>mouse</td><td>小鼠</td><td>体型小、耳大，室内常见</td></tr><tr><td>rodent</td><td>啮齿动物</td><td>分类类群，含两者</td></tr><tr><td>vermin</td><td>害兽</td><td>贬义，泛指有害鼠类</td></tr><tr><td>informer</td><td>告密者</td><td>只在&quot;叛徒&quot;义上对应</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>ræt</em></li><li><strong>Family:</strong> rat 大鼠 / rattrap 捕鼠夹 / ratty 破旧的；易怒的 / ratter 捕鼠的狗或猫</li><li><strong>Memory Tip:</strong> &quot;smell a rat&quot; 是&quot;觉得有鬼&quot;，来自狗嗅到鼠的气味。一个习语顺带记住 rat 的形象——总在暗处。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>rat 与 mouse 不可互换：rat 体型大、尾长、善游泳。</li><li>&quot;鼠患&quot;是 rat <strong>infestation</strong>，不用 <s>rat problem</s> 之外的生造词，但 rats problem 属语法错误。</li><li>拼写 rat，别与 <s>rate</s> 混。</li></ul></div><div class="vocab-card"><h2 id="squirrel" tabindex="-1"><a class="header-anchor" href="#squirrel"><span>Squirrel</span></a></h2><p class="vc-meta"><strong>/ˈskwɪrəl/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>松鼠</li><li>贮藏（动词，squirrel away）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a red squirrel</td><td>红松鼠</td></tr><tr><td>squirrels in the park</td><td>公园里的松鼠</td></tr><tr><td>squirrel away</td><td>偷偷囤积</td></tr><tr><td>a squirrel&#39;s cache</td><td>松鼠的储藏</td></tr><tr><td>grey squirrel</td><td>灰松鼠</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows how the grey squirrel&#39;s range expanded as the red squirrel&#39;s shrank.</p><blockquote><p>该图显示了灰松鼠的分布范围如何扩大，而红松鼠的如何缩小。</p></blockquote><p><strong>Writing Task 2</strong> Introduced grey squirrels carry a virus harmless to themselves but fatal to reds, which is why the two species cannot simply coexist.</p><blockquote><p>引入的灰松鼠携带一种对自己无害、对红松鼠致命的病毒，这就是两者无法简单共存的原因。</p></blockquote><p><strong>Speaking</strong> The squirrels here have worked out that tourists are an easier food source than trees.</p><blockquote><p>这里的松鼠已经发现，游客比树是更容易的食物来源。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>rodent</td><td>啮齿动物</td><td>上位类群</td></tr><tr><td>chipmunk</td><td>花栗鼠</td><td>有条纹，体型更小</td></tr><tr><td>marmot</td><td>旱獭</td><td>地面生活，体型大</td></tr><tr><td>hoard</td><td>囤积</td><td>只在&quot;贮藏&quot;义上接近</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊语 <em>skiouros</em>：skia（影子）+ oura（尾巴）→ &quot;尾巴能遮阴的&quot;</li><li><strong>Family:</strong> squirrel 松鼠 / squirrelly 古怪的（美式口语）/ squirrelled away 藏起来的</li><li><strong>Memory Tip:</strong> 词源是&quot;影子尾巴&quot;——松鼠那条蓬松大尾巴能给自己遮阳。记住这个画面，拼写里的 qu 与 rr 也不容易错。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写容易错：squir-rel，中间是 -irr-，不是 <s>-irel-</s>。</li><li>&quot;囤积&quot;是 <strong>squirrel away</strong>，带 away。</li><li>英式 /ˈskwɪrəl/，美式 /ˈskwɜːrəl/。</li></ul></div><div class="vocab-card"><h2 id="hare" tabindex="-1"><a class="header-anchor" href="#hare"><span>Hare</span></a></h2><p class="vc-meta"><strong>/heə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>野兔（比 rabbit 大、耳长、腿长，不挖洞）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a brown hare</td><td>棕色野兔</td></tr><tr><td>hares and rabbits</td><td>野兔与家兔</td></tr><tr><td>run like a hare</td><td>跑得飞快</td></tr><tr><td>a hare&#39;s ears</td><td>野兔的长耳</td></tr><tr><td>hare coursing</td><td>追猎野兔（非法活动）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the speed of hares and rabbits over short distances.</p><blockquote><p>该图比较了野兔与家兔在短距离内的速度。</p></blockquote><p><strong>Writing Task 2</strong> Unlike rabbits, hares do not burrow; they rely on speed and open ground, which makes them far more vulnerable to changes in land use.</p><blockquote><p>与家兔不同，野兔不挖洞，依靠速度与开阔地，这使它们对土地利用变化更为脆弱。</p></blockquote><p><strong>Speaking</strong> A hare shot out of the hedge and was gone before I&#39;d even focused my eyes.</p><blockquote><p>一只野兔从树篱里窜出，我眼睛还没对上焦它就没影了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>rabbit</td><td>家兔</td><td>体型小、挖洞，群居</td></tr><tr><td>bunny</td><td>小兔</td><td>儿语，多指宠物兔</td></tr><tr><td>jackrabbit</td><td>长耳兔</td><td>北美一种，实为野兔</td></tr><tr><td>rodent</td><td>啮齿动物</td><td>分类上兔形目不算啮齿目</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>hara</em></li><li><strong>Family:</strong> hare 野兔 / hare-brained 轻率的 / harebell 蓝铃花</li><li><strong>Memory Tip:</strong> hare 与 rabbit 的区别是生物学常考点：hare 大、耳长、不挖洞、幼崽生下来就有毛能睁眼；rabbit 小、挖洞、幼崽无毛。抓住&quot;洞&quot;这一点最好记。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>野兔 ≠ 家兔：hare 不挖洞、不成群。</li><li>兔形目不属于啮齿目，学术文本别说 <s>hare is a rodent</s>。</li><li>拼写 hare，别与 <s>hair</s> 混（同音不同义）。</li></ul></div><div class="vocab-card"><h2 id="penguin" tabindex="-1"><a class="header-anchor" href="#penguin"><span>Penguin</span></a></h2><p class="vc-meta"><strong>/ˈpeŋɡwɪn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>企鹅</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>emperor penguins</td><td>帝企鹅</td></tr><tr><td>a penguin colony</td><td>企鹅群</td></tr><tr><td>penguins huddle</td><td>企鹅挤成一团</td></tr><tr><td>penguin chicks</td><td>企鹅幼雏</td></tr><tr><td>a penguin&#39;s flippers</td><td>企鹅的鳍肢</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows the decline in penguin numbers on the island since 1980.</p><blockquote><p>该图显示了自 1980 年以来该岛企鹅数量的下降。</p></blockquote><p><strong>Writing Task 2</strong> Penguin colonies depend on sea ice as a nursery, so a single warm winter can wipe out an entire season&#39;s chicks.</p><blockquote><p>企鹅群以海冰为育幼场，因此一个偏暖的冬天就可能让整季的幼雏全部死亡。</p></blockquote><p><strong>Speaking</strong> Penguins walk like they&#39;re late for something important and slightly embarrassed about it.</p><blockquote><p>企鹅走路的样子像赶着去办件要紧事，又有点不好意思。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>seabird</td><td>海鸟</td><td>上位类群，含企鹅</td></tr><tr><td>puffin</td><td>海鹦</td><td>会飞，外形近似但不同科</td></tr><tr><td>auk</td><td>海雀</td><td>已灭绝的大海雀近亲</td></tr><tr><td>bird</td><td>鸟</td><td>上位类群</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 可能源自威尔士语 <em>pen gwyn</em>（白脑袋），或拉丁 <em>pinguis</em>（肥）</li><li><strong>Family:</strong> penguin 企鹅 / penguinery 企鹅繁殖地</li><li><strong>Memory Tip:</strong> 企鹅只分布在南半球，北极没有野生企鹅——这是常识考点，也是写作里常被误用的例子。记住&quot;南半球专属&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>企鹅不会飞，但翅膀是鳍肢（flippers），不能说 <s>penguin wings</s> 表&quot;飞行器官&quot;。</li><li>北极没有企鹅，写作别说 polar bears and penguins 同框（除动物园）。</li><li>拼写 pen-guin，注意 g 后接 u。</li></ul></div><div class="vocab-card"><h2 id="falcon" tabindex="-1"><a class="header-anchor" href="#falcon"><span>Falcon</span></a></h2><p class="vc-meta"><strong>/ˈfɔːlkən/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>隼（猛禽，飞行极快）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a peregrine falcon</td><td>游隼</td></tr><tr><td>a falcon&#39;s dive</td><td>隼的俯冲</td></tr><tr><td>falconry</td><td>驯鹰术</td></tr><tr><td>a hunting falcon</td><td>猎隼</td></tr><tr><td>falcon chicks</td><td>隼的幼鸟</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the maximum diving speed recorded for four bird species, with the falcon far ahead.</p><blockquote><p>该图显示了四种鸟记录到的最大俯冲速度，其中隼遥遥领先。</p></blockquote><p><strong>Writing Task 2</strong> Peregrine falcons once nested on cliffs but now increasingly use city towers, where pigeons provide a reliable supply of food.</p><blockquote><p>游隼曾在悬崖筑巢，如今越来越多地使用城市高楼，那里的鸽子提供了稳定的食物来源。</p></blockquote><p><strong>Speaking</strong> A falcon has nested on the office building, and there&#39;s now a live feed everyone watches instead of working.</p><blockquote><p>有只隼在办公楼筑了巢，现在大家不看工作，都看直播。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>hawk</td><td>鹰</td><td>泛称昼行猛禽，体型中等</td></tr><tr><td>eagle</td><td>雕</td><td>体型更大，翼展更宽</td></tr><tr><td>raptor</td><td>猛禽</td><td>分类学统称，含隼、鹰、鸮</td></tr><tr><td>kestrel</td><td>红隼</td><td>一种小型隼，悬停捕猎</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>falco</em>，可能与 <em>falx</em>（镰刀）有关，指翅形如镰</li><li><strong>Family:</strong> falcon 隼 / falconry 驯鹰术 / falconer 驯鹰人</li><li><strong>Memory Tip:</strong> 隼是&quot;镰刀翅&quot;——高速俯冲时翅膀后掠如镰。同族 falconry（驯鹰术）是中东传统运动，词形一并记。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>falcon 与 hawk、eagle 分属不同类：隼喙有齿突、翅尖长。</li><li>&quot;驯鹰术&quot;是 <strong>falconry</strong>，驯鹰人是 falconer，别生造 <s>falconing</s>。</li><li>拼写 fal-con，l 不发音 /ˈfɔːkən/（英式）。</li></ul></div><div class="vocab-card"><h2 id="hawk" tabindex="-1"><a class="header-anchor" href="#hawk"><span>Hawk</span></a></h2><p class="vc-meta"><strong>/hɔːk/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>鹰（中型昼行猛禽，如苍鹰、雀鹰）</li><li>鹰派人物（政治，hawk）</li><li>沿街叫卖（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a hawk circling</td><td>盘旋的鹰</td></tr><tr><td>hawks and doves</td><td>鹰派与鸽派</td></tr><tr><td>hawk watching</td><td>观鹰</td></tr><tr><td>a sparrowhawk</td><td>雀鹰</td></tr><tr><td>hawk-eyed</td><td>目光锐利的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the wing shape of a hawk compared with that of a falcon.</p><blockquote><p>该示意图比较了鹰与隼的翅型。</p></blockquote><p><strong>Writing Task 2</strong> Hawks and other raptors were once shot on sight, yet they are now the most reliable natural control on rodent numbers.</p><blockquote><p>鹰与其他猛禽曾一见到就被射杀，如今它们却是控制鼠类数量最可靠的自然手段。</p></blockquote><p><strong>Speaking</strong> A hawk sat on the fence for twenty minutes, and every bird in the garden vanished.</p><blockquote><p>一只鹰在篱笆上站了二十分钟，园子里的鸟全不见了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>eagle</td><td>雕</td><td>体型大，喜食鱼或大型猎物</td></tr><tr><td>falcon</td><td>隼</td><td>翅尖长，俯冲速度极快</td></tr><tr><td>raptor</td><td>猛禽</td><td>分类统称</td></tr><tr><td>kite</td><td>鸢</td><td>翅长、尾叉，滑翔觅食</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>hafoc</em></li><li><strong>Family:</strong> hawk 鹰 / hawkish 鹰派的 / hawk-eyed 目光锐利的 / hawk moth 天蛾</li><li><strong>Memory Tip:</strong> 政治里的&quot;鹰派&quot;（hawk）主张强硬，&quot;鸽派&quot;（dove）主张温和——用两种鸟的性格记两个立场，比背定义直观。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>鹰（hawk）、雕（eagle）、隼（falcon）三者不同，写作别用 eagle 泛称所有猛禽。</li><li>&quot;目光锐利&quot;是 <strong>hawk-eyed</strong>，一个词带连字符。</li><li>拼写 hawk，别与 <s>hock</s> 混。</li></ul></div><div class="vocab-card"><h2 id="eagle" tabindex="-1"><a class="header-anchor" href="#eagle"><span>Eagle</span></a></h2><p class="vc-meta"><strong>/ˈiːɡl/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>雕，鹰（大型猛禽）</li><li>（高尔夫）老鹰球（低于标准杆两杆）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a golden eagle</td><td>金雕</td></tr><tr><td>a bald eagle</td><td>白头海雕</td></tr><tr><td>an eagle&#39;s nest</td><td>雕巢</td></tr><tr><td>eagle-eyed</td><td>目光如鹰的</td></tr><tr><td>a pair of eagles</td><td>一对雕</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the number of breeding pairs of eagles recorded in the reserve.</p><blockquote><p>该图显示了保护区内记录到的雕繁殖对数。</p></blockquote><p><strong>Writing Task 2</strong> Eagles need huge territories and a stable food supply, so protecting the nest alone is pointless if the surrounding land is developed.</p><blockquote><p>雕需要广阔的领域与稳定的食物供给，因此如果周边土地被开发，只保护巢址毫无意义。</p></blockquote><p><strong>Speaking</strong> We saw an eagle once on a school trip and the teacher talked about it for the rest of the year.</p><blockquote><p>学校旅行时我们见过一次雕，老师之后一整年都在提这件事。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>hawk</td><td>鹰</td><td>体型较小，翅较圆</td></tr><tr><td>falcon</td><td>隼</td><td>翅尖长，速度型猎手</td></tr><tr><td>raptor</td><td>猛禽</td><td>分类统称</td></tr><tr><td>vulture</td><td>秃鹫</td><td>食腐为主，头颈裸露</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>aquila</em>（鹰）</li><li><strong>Family:</strong> eagle 雕 / eagle-eyed 敏锐的 / spread-eagle 展开四肢</li><li><strong>Memory Tip:</strong> 白头海雕（bald eagle）是美国的国鸟，出现频率极高。记住这个专名，eagle 的拼写与&quot;大型猛禽&quot;的含义就一并牢固。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>雕不是 hawk 的同义词，体型与习性不同。</li><li>&quot;鹰眼般敏锐&quot;是 <strong>eagle-eyed</strong>，用连字符。</li><li>拼写 ea-gle，注意与 <s>angle</s> 区分。</li></ul></div><div class="vocab-card"><h2 id="owl" tabindex="-1"><a class="header-anchor" href="#owl"><span>Owl</span></a></h2><p class="vc-meta"><strong>/aʊl/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>鸮，猫头鹰</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a barn owl</td><td>仓鸮</td></tr><tr><td>owls hoot</td><td>猫头鹰叫</td></tr><tr><td>a night owl</td><td>夜猫子（人）</td></tr><tr><td>an owl&#39;s eyesight</td><td>猫头鹰的视力</td></tr><tr><td>owl pellets</td><td>猫头鹰的食团</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows how owl numbers responded when the field was left unmown.</p><blockquote><p>该图显示了田地不再割草后猫头鹰数量的变化。</p></blockquote><p><strong>Writing Task 2</strong> Owls hunt by sound as much as by sight, and a noisy road can make an otherwise perfect habitat unusable.</p><blockquote><p>猫头鹰靠听觉捕猎不亚于靠视觉，一条嘈杂的公路就能让本来完美的栖息地变得无法使用。</p></blockquote><p><strong>Speaking</strong> We hear an owl most nights but have never actually seen it — it&#39;s become a bit of a family obsession.</p><blockquote><p>我们几乎每晚都听到猫头鹰叫，却从没真正看见过它，这已经成了全家的执念。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>raptor</td><td>猛禽</td><td>分类统称，含鸮</td></tr><tr><td>nightjar</td><td>夜鹰</td><td>夜行，但非猛禽</td></tr><tr><td>barn owl</td><td>仓鸮</td><td>具体一种，常见于农舍</td></tr><tr><td>bird of prey</td><td>猛禽</td><td>描述性说法</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>ūle</em>，拟声来源</li><li><strong>Family:</strong> owl 猫头鹰 / owlish 像猫头鹰的；学究气的 / night owl 夜猫子</li><li><strong>Memory Tip:</strong> &quot;night owl&quot;（夜猫子）是高频习语，指晚睡的人。记住这个用法，owl 的&quot;夜行&quot;特征就不用单独背了。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>猫头鹰是猛禽（raptor），不要与 hawk 混称。</li><li>&quot;夜猫子&quot;是 <strong>night owl</strong>，不是 <s>night cat</s>。</li><li>拼写 owl，别与 <s>awl</s>（锥子）混。</li></ul></div><div class="vocab-card"><h2 id="swallow" tabindex="-1"><a class="header-anchor" href="#swallow"><span>Swallow</span></a></h2><p class="vc-meta"><strong>/ˈswɒləʊ/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>燕子</li><li>吞下，咽下；（不自觉地）接受（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a barn swallow</td><td>家燕</td></tr><tr><td>swallows migrate</td><td>燕子迁徙</td></tr><tr><td>swallow a pill</td><td>吞药片</td></tr><tr><td>swallow the cost</td><td>承担费用</td></tr><tr><td>hard to swallow</td><td>难以接受</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the migration route of swallows between their breeding and wintering grounds.</p><blockquote><p>该地图显示了燕子在繁殖地与越冬地之间的迁徙路线。</p></blockquote><p><strong>Writing Task 2</strong> Swallows return to the same barn every spring, navigating by a combination of the sun, stars and the earth&#39;s magnetic field.</p><blockquote><p>燕子每年春天回到同一个谷仓，靠太阳、星辰与地磁场的组合导航。</p></blockquote><p><strong>Speaking</strong> I can&#39;t swallow pills — I have to break them in half, which is deeply annoying.</p><blockquote><p>我吞不下药片，只能掰成两半，特别烦。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>swift</td><td>雨燕</td><td>翅更长，几乎不落地</td></tr><tr><td>martin</td><td>毛脚燕</td><td>与燕近缘，巢形不同</td></tr><tr><td>gulp</td><td>大口吞</td><td>强调动作急促</td></tr><tr><td>accept</td><td>接受</td><td>只在引申义上对应</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>swalwe</em>（燕子）；动词义另有来源</li><li><strong>Family:</strong> swallow 燕子；吞咽 / swallowtail 凤蝶 / swallowable 可吞咽的</li><li><strong>Memory Tip:</strong> 一个词两条线：鸟与&quot;吞&quot;。英语里常拿&quot;吞&quot;比喻&quot;忍下&quot;——swallow your pride（咽下自尊），画面非常直白。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>作名词是燕子，作动词是吞咽，靠句法判断。</li><li>&quot;难以接受&quot;是 hard to <strong>swallow</strong>，不是 <s>hard to eat</s>。</li><li>拼写双 l：swa<strong>ll</strong>ow ✔</li></ul></div><div class="vocab-card"><h2 id="sparrow" tabindex="-1"><a class="header-anchor" href="#sparrow"><span>Sparrow</span></a></h2><p class="vc-meta"><strong>/ˈspærəʊ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>麻雀</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a house sparrow</td><td>家麻雀</td></tr><tr><td>sparrows in the street</td><td>街上的麻雀</td></tr><tr><td>a flock of sparrows</td><td>一群麻雀</td></tr><tr><td>sparrow numbers</td><td>麻雀数量</td></tr><tr><td>sparrows chirp</td><td>麻雀叽喳</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows the decline in house sparrow numbers in the city since 1990.</p><blockquote><p>该图显示了自 1990 年以来该市家麻雀数量的下降。</p></blockquote><p><strong>Writing Task 2</strong> House sparrows have almost vanished from central London, most likely because insect food for chicks has disappeared with the city&#39;s gardens.</p><blockquote><p>家麻雀几乎已从伦敦市中心消失，最可能的原因是雏鸟所需的昆虫食物随城市花园一起消失了。</p></blockquote><p><strong>Speaking</strong> Sparrows used to wake me up every morning here, and now I can&#39;t remember the last time I saw one.</p><blockquote><p>以前这儿的麻雀每天早上把我吵醒，现在我都想不起上次见到是什么时候。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>finch</td><td>雀</td><td>喙较粗，食种子为主</td></tr><tr><td>songbird</td><td>鸣禽</td><td>上位类群，含麻雀</td></tr><tr><td>starling</td><td>椋鸟</td><td>体型相近，羽色有光泽</td></tr><tr><td>chickadee</td><td>山雀</td><td>北美常见小型鸟</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>spearwa</em>（麻雀），与&quot;抖翅&quot;有关</li><li><strong>Family:</strong> sparrow 麻雀 / sparrowhawk 雀鹰 / sparrow-like 麻雀般的</li><li><strong>Memory Tip:</strong> 雀鹰（sparrowhawk）就是&quot;专门抓麻雀的鹰&quot;——两个词一拼，捕食关系也记住了，这正是英语复合词的妙处。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>麻雀与雀（finch）不同科，但中文都叫&quot;雀&quot;，英文要分清。</li><li>复数 sparrows；正式统计用 <strong>house sparrow</strong>。</li><li>拼写 sparrow 双 r：spa<strong>rr</strong>ow ✔</li></ul></div><div class="vocab-card"><h2 id="pigeon" tabindex="-1"><a class="header-anchor" href="#pigeon"><span>Pigeon</span></a></h2><p class="vc-meta"><strong>/ˈpɪdʒɪn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>鸽子（尤指城市里的原鸽）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>city pigeons</td><td>城市鸽子</td></tr><tr><td>a carrier pigeon</td><td>信鸽</td></tr><tr><td>pigeon droppings</td><td>鸽粪</td></tr><tr><td>a flock of pigeons</td><td>一群鸽子</td></tr><tr><td>pigeon racing</td><td>赛鸽</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the estimated pigeon population in each city district.</p><blockquote><p>该图显示了各城区的鸽子估计数量。</p></blockquote><p><strong>Writing Task 2</strong> Pigeons thrive in cities because tall buildings mimic the cliffs they evolved to nest on, and food waste removes any need to forage widely.</p><blockquote><p>鸽子在城市繁荣，因为高楼模拟了它们演化中筑巢的悬崖，而食物垃圾让它们无需远距离觅食。</p></blockquote><p><strong>Speaking</strong> A pigeon walked into the café and nobody said anything for a full ten seconds.</p><blockquote><p>一只鸽子走进咖啡馆，整整十秒没人说话。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>dove</td><td>鸽</td><td>体型更小、更纤细，多作和平象征</td></tr><tr><td>carrier pigeon</td><td>信鸽</td><td>专指传信品种</td></tr><tr><td>wood pigeon</td><td>斑尾林鸽</td><td>体型较大，林栖</td></tr><tr><td>feral pigeon</td><td>野化鸽</td><td>指城市中的野化原鸽</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>pipio</em>（啾啾叫的雏鸟）</li><li><strong>Family:</strong> pigeon 鸽子 / pigeonhole 归类；鸽笼格 / pigeon-toed 内八字</li><li><strong>Memory Tip:</strong> dove 与 pigeon 都指鸽：dove 纤细、象征和平，pigeon 圆胖、城市常见。两个词在英语里的&quot;气质&quot;完全不同，别混用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>和平鸽用 <strong>dove</strong>，城市鸽子用 pigeon。</li><li>拼写 pi-geon，注意中间是 eo。</li><li>pigeon 是可数名词，泛指用复数 pigeons。</li></ul></div><div class="vocab-card"><h2 id="crow" tabindex="-1"><a class="header-anchor" href="#crow"><span>Crow</span></a></h2><p class="vc-meta"><strong>/krəʊ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>乌鸦</li><li>公鸡打鸣（动词，crow）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a black crow</td><td>黑乌鸦</td></tr><tr><td>crows gather</td><td>乌鸦聚集</td></tr><tr><td>as the crow flies</td><td>直线距离</td></tr><tr><td>crow about ...</td><td>得意地吹嘘</td></tr><tr><td>a murder of crows</td><td>一群乌鸦（集合名词）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the change in crow numbers in farmland over twenty years.</p><blockquote><p>该图显示了二十年间农田中乌鸦数量的变化。</p></blockquote><p><strong>Writing Task 2</strong> Crows solve problems that would stump a five-year-old child, and some can recognise individual human faces for years.</p><blockquote><p>乌鸦能解决五岁孩子都搞不定的问题，有些还能记住某张人脸好几年。</p></blockquote><p><strong>Speaking</strong> The crows here have learned to drop nuts on the crossing so cars crack them open.</p><blockquote><p>这里的乌鸦学会了把坚果丢在斑马线上，让车替它们压开。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>raven</td><td>渡鸦</td><td>体型更大，鸣声低沉</td></tr><tr><td>rook</td><td>秃鼻乌鸦</td><td>群居，农田常见</td></tr><tr><td>magpie</td><td>喜鹊</td><td>黑白相间，喜收集亮物</td></tr><tr><td>jay</td><td>松鸦</td><td>羽色带蓝，林中常见</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>crāwe</em>，拟声词，模仿叫声</li><li><strong>Family:</strong> crow 乌鸦；打鸣 / crowbar 撬棍 / scarecrow 稻草人</li><li><strong>Memory Tip:</strong> scarecrow（稻草人）字面就是&quot;吓乌鸦的东西&quot;， crowbar（撬棍）因形如鸦爪而得名。两个常见词把 crow 钉住。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>动词 crow 指公鸡打鸣，也可指&quot;得意吹嘘&quot;，注意语境。</li><li>&quot;直线距离&quot;是 as the crow <strong>flies</strong>，不是 <s>as the crow goes</s>。</li><li>拼写 crow，别与 <s>cow</s> 混。</li></ul></div><div class="vocab-card"><h2 id="swan" tabindex="-1"><a class="header-anchor" href="#swan"><span>Swan</span></a></h2><p class="vc-meta"><strong>/swɒn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>天鹅</li><li>闲逛（动词，英式口语 swan around）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a mute swan</td><td>疣鼻天鹅</td></tr><tr><td>swans on the lake</td><td>湖上的天鹅</td></tr><tr><td>a swan&#39;s neck</td><td>天鹅颈</td></tr><tr><td>swan song</td><td>天鹅之歌；最后的作品</td></tr><tr><td>swans mate for life</td><td>天鹅终生配对</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the number of swans counted on the river each winter.</p><blockquote><p>该图显示了每年冬天在河上统计到的天鹅数量。</p></blockquote><p><strong>Writing Task 2</strong> Swans need shallow, slow-moving water with plenty of submerged plants, so dredging a river can destroy a population that has been stable for centuries.</p><blockquote><p>天鹅需要长满沉水植物的浅缓水域，因此河道清淤可能摧毁一个已稳定数百年的种群。</p></blockquote><p><strong>Speaking</strong> The swans on the canal have absolutely no fear of people and will chase you for bread.</p><blockquote><p>运河上的天鹅完全不怕人，会为了面包追你。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>goose</td><td>鹅</td><td>体型较小，颈较短</td></tr><tr><td>cygnet</td><td>幼天鹅</td><td>天鹅的幼体</td></tr><tr><td>duck</td><td>鸭</td><td>体型更小，喙扁</td></tr><tr><td>waterfowl</td><td>水禽</td><td>上位类群，含鸭、鹅、天鹅</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>swan</em></li><li><strong>Family:</strong> swan 天鹅 / cygnet 幼天鹅 / swan song 天鹅之歌 / swan-necked 天鹅颈的</li><li><strong>Memory Tip:</strong> 幼天鹅叫 <strong>cygnet</strong>（来自拉丁 cygnus），幼鹅叫 gosling，幼鸭叫 duckling——三种水禽幼体专名一起记，写作才不至于一律用 baby。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>幼天鹅是 <strong>cygnet</strong>，不要说 <s>baby swan</s>（口语可，但正式文本宜用专名）。</li><li>&quot;天鹅之歌&quot;是 <strong>swan song</strong>，指最后的作品或表演。</li><li>拼写 swan，别与 <s>sworn</s> 混。</li></ul></div><div class="vocab-card"><h2 id="goose" tabindex="-1"><a class="header-anchor" href="#goose"><span>Goose</span></a></h2><p class="vc-meta"><strong>/ɡuːs/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>鹅（比天鹅小，颈较短）</li><li>傻瓜（口语，贬义）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a wild goose</td><td>大雁</td></tr><tr><td>geese flying south</td><td>南飞的大雁</td></tr><tr><td>goose down</td><td>鹅绒</td></tr><tr><td>a goose&#39;s honk</td><td>鹅叫</td></tr><tr><td>kill the goose that lays the golden eggs</td><td>杀鸡取卵</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the number of geese wintering in the estuary over three decades.</p><blockquote><p>该图比较了三十年间在该河口越冬的雁类数量。</p></blockquote><p><strong>Writing Task 2</strong> Migratory geese link habitats across continents, so a single drained wetland can affect populations thousands of kilometres away.</p><blockquote><p>迁徙的雁类把各大洲的栖息地连接起来，因此一片被排干的湿地可能影响数千公里外的种群。</p></blockquote><p><strong>Speaking</strong> The geese by the lake are aggressive enough that people now walk the long way round.</p><blockquote><p>湖边的鹅凶得人们现在都绕远路走。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>swan</td><td>天鹅</td><td>颈更长，体型更大</td></tr><tr><td>duck</td><td>鸭</td><td>体型小，喙扁宽</td></tr><tr><td>gander</td><td>公鹅</td><td>成年雄性</td></tr><tr><td>gosling</td><td>幼鹅</td><td>雏鹅</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>gōs</em>，与德语 <em>Gans</em> 同源</li><li><strong>Family:</strong> geese 复数 / gosling 幼鹅 / goose bumps 鸡皮疙瘩</li><li><strong>Memory Tip:</strong> 不规则复数 goose→<strong>geese</strong>（像 foot→feet）。另记 goose bumps（鸡皮疙瘩）——冷起来皮肤像拔了毛的鹅，画面很直观。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>复数 <strong>geese</strong>，不是 <s>gooses</s>。</li><li>公鹅 <strong>gander</strong>、母鹅 <strong>goose</strong>、幼鹅 <strong>gosling</strong>，三个专名分开记。</li><li>&quot;杀鸡取卵&quot;英语说 kill the goose that lays the golden eggs。</li></ul></div><div class="vocab-card"><h2 id="cock" tabindex="-1"><a class="header-anchor" href="#cock"><span>Cock</span></a></h2><p class="vc-meta"><strong>/kɒk/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>公鸡（英式；美式多用 rooster）</li><li>雄鸟（用于复合词，如 cock pheasant）</li><li>翘起，竖起（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a cock crowing</td><td>公鸡打鸣</td></tr><tr><td>cock pheasant</td><td>雄雉</td></tr><tr><td>at cock crow</td><td>鸡鸣时分</td></tr><tr><td>cock of the walk</td><td>自命不凡者</td></tr><tr><td>cock its head</td><td>歪着头</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the growth rate of cocks and hens on the two farms.</p><blockquote><p>该图比较了两个农场上公鸡与母鸡的生长速度。</p></blockquote><p><strong>Writing Task 2</strong> In many villages the cock&#39;s crow still sets the rhythm of the morning, even where every household owns an alarm clock.</p><blockquote><p>在许多村庄，公鸡的啼叫仍定着清晨的节奏，即便家家都有闹钟。</p></blockquote><p><strong>Speaking</strong> The neighbour&#39;s cock starts at four, which has made me deeply unpopular at breakfast.</p><blockquote><p>邻居的公鸡四点就开始叫，这让我在早餐桌上非常不受欢迎。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>rooster</td><td>公鸡</td><td>美式常用，避免歧义</td></tr><tr><td>cockerel</td><td>小公鸡</td><td>未满一岁的雄鸡</td></tr><tr><td>hen</td><td>母鸡</td><td>成年雌性</td></tr><tr><td>chick</td><td>小鸡</td><td>雏鸡</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>cocc</em>，拟声词</li><li><strong>Family:</strong> cock 公鸡 / cockerel 小公鸡 / cockcrow 鸡鸣 / peacock 孔雀</li><li><strong>Memory Tip:</strong> peacock（孔雀）字面就是&quot;pea（ peahen 的雄鸟）+ cock&quot;，即&quot;雄孔雀&quot;。同族的 cock 表示&quot;雄性&quot;，在动物名里反复出现。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>美式英语中 cock 有粗俗联想，指公鸡优先用 <strong>rooster</strong>。</li><li>母鸡是 <strong>hen</strong>，小鸡是 <strong>chick</strong>，三者不能混。</li><li>拼写 cock，注意与 <s>cook</s> 区分。</li></ul></div>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};